<script setup lang="ts">
import {ref,computed,watch,nextTick} from 'vue'
import {IconPencil,IconFileDescription,IconArrowRight,IconLock,IconRefresh} from '@tabler/icons-vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import {createProfileApi,type ProfileSection} from './profile-api'
import {useParticipantProfile} from './useParticipantProfile'
import {referenceKinds,chapters,referenceName,type Catalogue,type Reference} from './profile-fields'
import ProfileOverview from './ProfileOverview.vue'
import ProfileWizard from './ProfileWizard.vue'
import ProfileSectionEditor from './ProfileSectionEditor.vue'
import './profile.css'
type S=components['schemas']
const props=defineProps<{client:SessionClient;member:S['MemberView'];ru:boolean;active:boolean;participants:S['ParticipantView'][];relations:S['RelationView'][]}>()
const emit=defineEmits<{saved:[S['MemberView']]}>()
const state=useParticipantProfile(createProfileApi(props.client))
const {published,document,draft,step,loading,saving,error,dirty}=state
const catalogue=ref<Catalogue>({}),catalogueError=ref(''),wizard=ref(false),editing=ref<ProfileSection|null>(null),tab=ref('overview'),notice=ref('')
const currentSection=computed(()=>chapters[step.value-1]![0])
const partners=computed(()=>{const ids=new Set(props.relations.filter(r=>r.status==='active'&&(r.dominant_user_id===props.member.id||r.submissive_user_id===props.member.id)).map(r=>r.dominant_user_id===props.member.id?r.submissive_user_id:r.dominant_user_id));return props.participants.filter(p=>ids.has(p.id))})
const bio=computed(()=>published.value?.document.identity.bio)
const roleLabels=computed(()=>published.value?.document.dynamics?.profile_labels??props.member.profile_labels)
const relationships=computed(()=>(published.value?.document.dynamics?.relationship_type_uids??[]).map(id=>referenceName(catalogue.value,id)).join(' / '))
const tabs=computed(()=>[['overview','Обзор','Overview'],['preferences','Предпочтения','Preferences'],['boundaries','Границы','Boundaries'],['health','Здоровье','Health & care']])
let run=0
async function load(){const id=++run;await state.load();try{const rows=await Promise.all(referenceKinds.map(async kind=>[kind,await props.client.get<Reference[]>('/references/'+kind)] as const));if(id===run){catalogue.value=Object.fromEntries(rows);catalogueError.value=''}}catch{if(id===run)catalogueError.value=props.ru?'Не удалось загрузить справочники. Повторите попытку.':'Could not load catalogues. Please retry.'}}
watch(()=>props.member.id,()=>{wizard.value=false;editing.value=null;tab.value='overview';load()},{immediate:true})
watch(()=>props.active,active=>{if(active&&!wizard.value&&!editing.value&&published.value&&published.value.account_version!==props.member.profile_version)state.load()})
async function refreshAccount(){emit('saved',await props.client.get<S['MemberView']>('/me'))}
async function startWizard(){if(editing.value&&!await state.saveSection(editing.value,chapters.findIndex(c=>c[0]===editing.value)+1))return;notice.value='';editing.value=null;wizard.value=true;await nextTick();focusHeading()}
function focusHeading(){window.document.getElementById('wizard-heading')?.focus()}
async function move(next:number){if(await state.goToStep(next,currentSection.value)){await nextTick();focusHeading()}}
async function exit(){if(await state.defer(currentSection.value)){wizard.value=false;notice.value=props.ru?'Черновик сохранён. Продолжите в удобное время.':'Draft saved. Continue whenever you like.'}}
async function finish(){if(await state.saveSection('visibility',6)&&await state.publish()){wizard.value=false;editing.value=null;tab.value='overview';await refreshAccount();notice.value=props.ru?'Профиль сохранён':'Profile saved'}}
async function edit(section:ProfileSection){notice.value='';if(editing.value&&editing.value!==section&&!await state.saveSection(editing.value))return;editing.value=section;tab.value=section==='identity'||section==='dynamics'||section==='visibility'?'overview':section}
async function save(){if(editing.value&&await state.saveSection(editing.value)&&await state.publish()){editing.value=null;await refreshAccount();notice.value=props.ru?'Профиль сохранён':'Profile saved'}}
async function changeTab(value:string){if(editing.value&&!await state.saveSection(editing.value))return;editing.value=null;tab.value=value;if(value!=='overview')editing.value=value as ProfileSection}
async function discard(){if(await state.discard()){editing.value=null;wizard.value=false;notice.value=props.ru?'Черновик удалён':'Draft discarded'}}
const message=computed(()=>error.value==='CONFLICT'?(props.ru?'Профиль изменён в другой вкладке. Ваш текст остаётся в форме. Обновите данные или удалите устаревший черновик.':'Profile changed in another tab. Your text remains in this form. Reload or discard the stale draft.'):error.value==='INVALID_INPUT'?(props.ru?'Проверьте заполненные поля и доступность выбранных партнёров.':'Check the fields and selected partners.'):error.value?(props.ru?'Не удалось сохранить. Ваши изменения остаются в форме.':'Could not save. Your changes remain in this form.'):'')
</script>
<template><section class="participant-profile"><p v-if="loading" role="status">{{ru?'Загружаем профиль…':'Loading profile…'}}</p><div v-if="error||catalogueError" class="profile-error" role="alert"><p>{{message||catalogueError}}</p><button class="quiet-button" :disabled="saving" @click="load"><IconRefresh :size="16"/>{{ru?'Обновить данные':'Reload data'}}</button><button v-if="draft&&error==='CONFLICT'" class="quiet-button" :disabled="saving" @click="discard">{{ru?'Удалить черновик':'Discard draft'}}</button></div><p v-if="notice" class="profile-saved" role="status">{{notice}}</p><template v-if="published&&document&&!loading"><ProfileWizard v-if="wizard" :step="step" :ru="ru" :busy="saving" @step="move" @next="move(Math.min(step+1,6))" @skip="move(Math.min(step+1,6))" @back="move(Math.max(step-1,1))" @exit="exit" @publish="finish"><fieldset class="profile-edit-fields" :disabled="saving"><ProfileSectionEditor v-model="document" :section="currentSection" :catalogue="catalogue" :partners="partners" :ru="ru" @update:model-value="dirty=true"/></fieldset><div v-if="step===6" class="profile-final-review"><h3>{{ru?'Перед сохранением':'Before publishing'}}</h3><p>{{document.identity.display_name}} · {{ru?'Выбранных практик: ':'Selected practices: '}}{{document.preferences?.practices?.length??0}}</p><p class="muted">{{ru?'Партнёры увидят только открытые им разделы.':'Partners will only see sections you explicitly share.'}}</p></div></ProfileWizard><template v-else><header class="profile-passport-identity"><span class="profile-avatar" aria-hidden="true">{{published.document.identity.display_name.slice(0,1)}}</span><div><span class="profile-eyebrow">{{ru?'ЛИЧНЫЙ ПАСПОРТ':'PERSONAL PROFILE'}}</span><h2>{{published.document.identity.display_name}}</h2><p v-if="roleLabels.length||relationships" class="profile-dynamics-line">{{roleLabels.map(role=>role.charAt(0).toUpperCase()+role.slice(1)).join(' / ')}}<template v-if="roleLabels.length&&relationships"> · </template>{{relationships}}</p><p v-if="bio" class="profile-bio">{{bio}}</p><p v-else class="profile-bio muted">{{ru?'Расскажите о себе и о том, что для вас важно.':'Share a little about yourself and what matters to you.'}}</p></div><button :disabled="saving" class="profile-edit-main" @click="edit('identity')"><IconPencil :size="17"/>{{ru?'Редактировать профиль':'Edit profile'}}</button></header><aside v-if="!published.progress.completed||draft" class="profile-onboarding-banner"><IconFileDescription :size="28"/><div><h3>{{draft?(ru?'Продолжим ваш профиль?':'Continue your profile?'):(ru?'Дополним ваш профиль?':'Build your profile?')}}</h3><p>{{ru?'Можно по шагам и в удобное время.':'One step at a time, whenever you like.'}}</p></div><button :disabled="saving" @click="startWizard">{{draft?(ru?'Продолжить заполнение':'Continue setup'):(ru?'Начать заполнение':'Start setup')}}<IconArrowRight :size="17"/></button><button v-if="!draft?.deferred" class="quiet-button" :disabled="saving" @click="state.defer().then(ok=>{if(ok)notice=ru?'Продолжить можно позже':'Continue later'})">{{ru?'Позже':'Later'}}</button></aside><nav class="profile-inner-tabs" :aria-label="ru?'Разделы профиля':'Profile sections'"><button v-for="item in tabs" :key="item[0]" :aria-current="tab===item[0]?'page':undefined" :class="{active:tab===item[0]}" :disabled="saving" @click="changeTab(item[0]!)">{{item[ru?1:2]}}</button><button class="profile-visibility-tab" :disabled="saving" @click="edit('visibility')"><IconLock :size="16"/>{{ru?'Видимость':'Visibility'}}</button></nav><section v-if="editing" class="profile-inline-editor"><header><h3>{{chapters.find(c=>c[0]===editing)?.[ru?1:2]}}</h3><span class="profile-private-label">{{ru?'Черновик · только я':'Draft · only me'}}</span></header><fieldset class="profile-edit-fields" :disabled="saving"><ProfileSectionEditor v-model="document" :section="editing" :catalogue="catalogue" :partners="partners" :ru="ru" @update:model-value="dirty=true"/></fieldset><footer class="profile-editor-actions"><button :disabled="saving" @click="save">{{saving?(ru?'Сохранение…':'Saving…'):(ru?'Сохранить профиль':'Save profile')}}</button><button class="quiet-button" :disabled="saving" @click="startWizard">{{ru?'Заполнить по шагам':'Use guided setup'}}</button><button class="quiet-button" :disabled="saving" @click="edit(editing==='identity'?'dynamics':'identity')">{{editing==='identity'?(ru?'Динамика':'Dynamics'):(ru?'О себе':'About me')}}</button><button v-if="draft" class="quiet-button" :disabled="saving" @click="discard">{{ru?'Удалить черновик':'Discard draft'}}</button></footer></section><template v-else><ProfileOverview :document="published.document" :catalogue="catalogue" :ru="ru" @edit="edit"/><button class="quiet-button profile-reopen-wizard" @click="startWizard">{{ru?'Заполнить профиль по шагам':'Open guided profile setup'}}<IconArrowRight :size="16"/></button></template></template></template></section></template>
